import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:unorm_dart/unorm_dart.dart' as unorm;

/// The credentials of a sync account: an email and a password.
///
/// Credentials can be typed in or read from an older
/// `linguasrs://sync?...` link. New device pairing uses encrypted, one-time
/// `linguasrs://pair?...` links generated by the account service.
///
/// Every account lives on the hosted sync server, whose address is set when
/// the app is built (see [defaultEndpoint]). A link only names a server when
/// it differs, for a local `wrangler dev` Worker.
///
/// The password is never sent to the server as it is. It is the root of the
/// keys that authenticate the device and encrypt its data (see
/// `docs/sync.md`). Sign-in therefore accepts any non-empty password; the
/// password rules apply when an account is created.
class SyncPairing {
  static const scheme = 'linguasrs';
  static const host = 'sync';

  static final _emailPattern = RegExp(r'^[^\s@:]+@[^\s@:]+\.[^\s@:]+$');

  /// Plain http is only accepted for a Worker running locally (`wrangler dev`
  /// or the Android emulator's host alias).
  static const _loopbackHosts = {'localhost', '127.0.0.1', '::1', '10.0.2.2'};

  static Uri? _defaultEndpoint = _endpointFromEnvironment();

  /// The hosted Worker every account uses, from the `SYNC_ENDPOINT` build
  /// setting. It is null in a build without one, which has no sync.
  static Uri? get defaultEndpoint => _defaultEndpoint;

  @visibleForTesting
  static set defaultEndpoint(Uri? value) {
    _defaultEndpoint = value == null ? null : _normalizeEndpoint(value);
  }

  /// Base address of the Worker, without a trailing slash.
  final Uri endpoint;

  /// Identifies the account; lowercase, with no surrounding whitespace.
  final String email;

  /// Never shown in logs.
  final String password;

  const SyncPairing._(this.endpoint, this.email, this.password);

  /// Validates and normalizes the parts, using [defaultEndpoint] when no
  /// [endpoint] is given. The [email] is trimmed and lowercased; the
  /// [password] is kept exactly as typed. Throws [FormatException] if any part
  /// cannot be used.
  factory SyncPairing({
    Uri? endpoint,
    required String email,
    required String password,
  }) {
    final normalizedEmail = normalizeEmail(email);
    if (!_emailPattern.hasMatch(normalizedEmail) ||
        !_isWellFormed(normalizedEmail)) {
      throw const FormatException('Email is missing or invalid.');
    }
    if (password.trim().isEmpty) {
      throw const FormatException('Password is missing.');
    }
    if (!_isWellFormed(password)) {
      throw const FormatException(
        'Password has characters that cannot be saved.',
      );
    }
    final server = endpoint ?? _defaultEndpoint;
    if (server == null) {
      throw const FormatException('This build has no sync server configured.');
    }
    return SyncPairing._(_normalizeEndpoint(server), normalizedEmail, password);
  }

  /// Reads a legacy sign-in link or a link pasted by hand.
  /// Surrounding whitespace is ignored. Throws [FormatException] otherwise.
  factory SyncPairing.parse(String text) {
    const notALink = FormatException('Not a LinguaSRS sync link.');
    final Uri uri;
    try {
      uri = Uri.parse(text.trim());
    } on FormatException {
      throw notALink;
    }
    if (uri.scheme != scheme || uri.host != host) throw notALink;

    final endpointText = _queryValue(uri, 'endpoint');
    final endpoint = endpointText == null ? null : Uri.tryParse(endpointText);
    if (endpointText != null && endpoint == null) {
      throw const FormatException('Sync link has an invalid server address.');
    }
    return SyncPairing(
      endpoint: endpoint,
      email: _queryValue(uri, 'email') ?? '',
      password: _queryValue(uri, 'password') ?? '',
    );
  }

  /// The value of the query parameter [name], or null if the link has none.
  ///
  /// [Uri.queryParameters] cannot be used: its UTF-8 decoder drops a leading
  /// byte order mark (U+FEFF), so a password that starts with one would lose
  /// it when the saved link is read back.
  static String? _queryValue(Uri uri, String name) {
    for (final pair in uri.query.split('&')) {
      final equals = pair.indexOf('=');
      final key = equals < 0 ? pair : pair.substring(0, equals);
      if (_decodeQueryValue(key) != name) continue;
      return equals < 0 ? '' : _decodeQueryValue(pair.substring(equals + 1));
    }
    return null;
  }

  static final _hexByte = RegExp(r'^[0-9a-fA-F]{2}$');

  static String _decodeQueryValue(String raw) {
    // A leading sentinel byte stops the decoder from treating a U+FEFF at the
    // start of the text as a byte order mark and dropping it.
    final bytes = <int>[0x41];
    var literal = StringBuffer();
    void flush() {
      // Literal text is encoded in whole runs so a surrogate pair stays one
      // character.
      if (literal.isEmpty) return;
      bytes.addAll(utf8.encode(literal.toString()));
      literal = StringBuffer();
    }

    for (var i = 0; i < raw.length; i++) {
      final char = raw[i];
      if (char == '%' &&
          i + 2 < raw.length &&
          _hexByte.hasMatch(raw.substring(i + 1, i + 3))) {
        flush();
        bytes.add(int.parse(raw.substring(i + 1, i + 3), radix: 16));
        i += 2;
      } else if (char == '+') {
        flush();
        bytes.add(0x20);
      } else {
        literal.write(char);
      }
    }
    flush();
    return utf8.decode(bytes, allowMalformed: true).substring(1);
  }

  Uri toUri() => Uri(
    scheme: scheme,
    host: host,
    queryParameters: {
      if (endpoint != _defaultEndpoint) 'endpoint': endpoint.toString(),
      'email': email,
      'password': password,
    },
  );

  /// The legacy credential link format, which contains the password.
  String get link => toUri().toString();

  /// An email as the account knows it: trimmed, in Unicode form NFKC and
  /// lowercase, so that equivalent spellings (full-width letters, an accent
  /// typed as one character or two) are the same account. The Worker applies
  /// the same steps in the same order.
  static String normalizeEmail(String email) =>
      unorm.nfkc(unorm.nfkc(email.trim()).toLowerCase());

  /// A Dart string can hold half of a surrogate pair, which has no UTF-8 form,
  /// so it could not be kept in a link or sent to the server. It is refused
  /// instead of being silently changed.
  static bool _isWellFormed(String text) {
    final units = text.codeUnits;
    for (var i = 0; i < units.length; i++) {
      final unit = units[i];
      if (unit >= 0xD800 && unit <= 0xDBFF) {
        final paired =
            i + 1 < units.length &&
            units[i + 1] >= 0xDC00 &&
            units[i + 1] <= 0xDFFF;
        if (!paired) return false;
        i++;
      } else if (unit >= 0xDC00 && unit <= 0xDFFF) {
        return false;
      }
    }
    return true;
  }

  /// Checks and normalizes a server address, throwing [FormatException] if it
  /// cannot be used. Plain http is only accepted for a local Worker.
  static Uri normalizeServer(Uri endpoint) => _normalizeEndpoint(endpoint);

  static Uri? _endpointFromEnvironment() {
    const value = String.fromEnvironment('SYNC_ENDPOINT');
    return value.isEmpty ? null : _normalizeEndpoint(Uri.parse(value));
  }

  static Uri _normalizeEndpoint(Uri endpoint) {
    final secure = endpoint.scheme == 'https';
    final local =
        endpoint.scheme == 'http' && _loopbackHosts.contains(endpoint.host);
    if (endpoint.host.isEmpty || !(secure || local)) {
      throw const FormatException('Sync server must be an https:// address.');
    }
    if (endpoint.hasQuery ||
        endpoint.hasFragment ||
        endpoint.userInfo.isNotEmpty) {
      throw const FormatException(
        'Sync server address cannot have a query, fragment or login.',
      );
    }
    var path = endpoint.path;
    while (path.endsWith('/')) {
      path = path.substring(0, path.length - 1);
    }
    return endpoint.replace(path: path);
  }

  @override
  bool operator ==(Object other) =>
      other is SyncPairing &&
      other.endpoint == endpoint &&
      other.email == email &&
      other.password == password;

  @override
  int get hashCode => Object.hash(endpoint, email, password);

  @override
  String toString() => 'SyncPairing($endpoint, $email, password: ***)';
}
